import{_ as o,C as s,o as i,c as r,aj as t,E as n}from"./framework.js";const u=JSON.parse('{"title":"IndexedDB Table Relations | Database | Admin CMS","description":"Table relations declare an association between two IndexedDB tables: specify Table A / Field A, relation type, Table B / Field B, and give the relation a name. After saving, when reading…","frontmatter":{"title":"IndexedDB Table Relations | Database | Admin CMS","description":"Table relations declare an association between two IndexedDB tables: specify Table A / Field A, relation type, Table B / Field B, and give the relation a name. After saving, when reading…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/database/table-relation.html"}]]},"headers":[],"relativePath":"cms/database/table-relation.md","filePath":"en/cms/database/table-relation.md","lastUpdated":1781010536000}'),l={name:"cms/database/table-relation.md"};function d(h,e,b,c,g,p){const a=s("DocImage");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="indexeddb-table-relations" tabindex="-1">IndexedDB Table Relations <a class="header-anchor" href="#indexeddb-table-relations" aria-label="Permalink to &quot;IndexedDB Table Relations&quot;">​</a></h1><blockquote><p>Menu: <strong>Database → IndexedDB Table Relations</strong><br> Deep link: <code>/_Admin/database/table-relation?SiteId={siteGuid}</code></p></blockquote><p><strong>Table relations</strong> declare an association between two <a href="./table.html">IndexedDB tables</a>: specify <strong>Table A / Field A</strong>, <strong>relation type</strong>, <strong>Table B / Field B</strong>, and give the relation a <strong>name</strong>. After saving, when reading a row from Table A in KScript, you can access related Table B data through the <strong>relation name</strong> (or in some scenarios the related table name).</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><p>List and view: <code>tableRelation</code> (view). <strong>New</strong> relations require <code>tableRelation·edit</code>; multi-select <strong>Delete</strong> requires <code>tableRelation·delete</code>.</p></div><div class="info custom-block"><p class="custom-block-title">Prerequisites</p><p>Both tables must already exist under <strong>IndexedDB Tables</strong>, and the related fields must exist in <strong>Column settings</strong>. Tables and fields in dropdowns come from the current site’s IndexedDB table schema.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, check <strong>Database → IndexedDB Table Relations</strong>.</li><li>Open <strong>Database → IndexedDB Table Relations</strong> in the left sidebar.</li></ol>',7)),n(a,{src:"/cms/database/table-relation-overview.png",alt:"Table relation list",width:"1120"}),e[1]||(e[1]=t('<h2 id="relation-list" tabindex="-1">Relation List <a class="header-anchor" href="#relation-list" aria-label="Permalink to &quot;Relation List&quot;">​</a></h2><h3 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><strong>New</strong></td><td><code>tableRelation·edit</code></td><td>Opens the <a href="#new-relation-dialog">new relation dialog</a></td></tr></tbody></table>',3)),n(a,{src:"/cms/database/table-relation-toolbar.png",alt:"Table relation toolbar",width:"1120"}),e[2]||(e[2]=t('<h3 id="list-table" tabindex="-1">List table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Unique relation name; in scripts often used as the <strong>property name</strong> on the current table record to access related data</td></tr><tr><td><strong>Table A</strong> / <strong>Field A</strong></td><td>Table and field on one side of the relation</td></tr><tr><td><strong>Relation</strong></td><td>Relation type (one-to-one, one-to-many, many-to-many, many-to-one; UI labels are localized)</td></tr><tr><td><strong>Table B</strong> / <strong>Field B</strong></td><td>Table and field on the other side</td></tr></tbody></table><p>Supports multi-select <strong>Delete</strong>. The UI does <strong>not</strong> provide inline editing; to change a relation, delete and <strong>New</strong> again (or update via the <code>TableRelation</code> API).</p>',3)),n(a,{src:"/cms/database/table-relation-list.png",alt:"Table relation list table",width:"1120"}),e[3]||(e[3]=t('<h2 id="new-relation-dialog" tabindex="-1">New Relation Dialog <a class="header-anchor" href="#new-relation-dialog" aria-label="Permalink to &quot;New Relation Dialog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Required; 1–50 characters; unique within the site (prompts if the relation name already exists)</td></tr><tr><td><strong>Table A</strong></td><td>Select an IndexedDB table</td></tr><tr><td><strong>Field A</strong></td><td>Field list after Table A is selected</td></tr><tr><td><strong>Relation</strong></td><td>Relation type: <strong>OneOne</strong>, <strong>OneMany</strong>, <strong>ManyMany</strong>, <strong>ManyOne</strong> (UI shows localized labels)</td></tr><tr><td><strong>Table B</strong></td><td>Another IndexedDB table</td></tr><tr><td><strong>Field B</strong></td><td>Associated field on Table B</td></tr></tbody></table><p>After save, calls <code>TableRelation/post</code> to write to the site database; the list refreshes.</p>',3)),n(a,{src:"/cms/database/table-relation-create-dialog.png",alt:"New table relation dialog",width:"1120"}),e[4]||(e[4]=t(`<h3 id="relation-type-meanings-in-use" tabindex="-1">Relation type meanings (in use) <a class="header-anchor" href="#relation-type-meanings-in-use" aria-label="Permalink to &quot;Relation type meanings (in use)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Typical meaning</th><th>Script expansion (accessing from a Table A row)</th></tr></thead><tbody><tr><td><strong>One-to-one / many-to-one</strong></td><td>One A record maps to one B record</td><td>Single related object</td></tr><tr><td><strong>One-to-many / many-to-many</strong></td><td>One A record maps to multiple B records</td><td><strong>Array</strong> of related objects</td></tr></tbody></table><p>The actual join matches <strong>Field A</strong> and <strong>Field B</strong> values (e.g. <code>users.id</code> to <code>orders.userId</code>).</p><h2 id="effect-in-scripts" tabindex="-1">Effect in scripts <a class="header-anchor" href="#effect-in-scripts" aria-label="Permalink to &quot;Effect in scripts&quot;">​</a></h2><p>Relations do <strong>not</strong> expose a separate <code>k.*</code> API. After querying an <a href="./table.html">IndexedDB table</a> and getting a dynamic object, use the <strong>relation name</strong> to read related data:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.indexedDb.users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(userId)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Assume a relation named userOrders: users.id → orders.userId, one-to-many</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> orders</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user.userOrders</span></span></code></pre></div><ul><li>The access name usually matches the <strong>Name</strong> entered in the admin.</li><li>One-to-many / many-to-many return arrays; one-to-one / many-to-one return a single object.</li><li>More CRUD details: <a href="/kb-docs/api/indexed-db/">k.DB.indexedDb</a>.</li></ul><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical workflow&quot;">​</a></h2><ol><li>Prepare <strong>Table A</strong>, <strong>Table B</strong>, and association fields under <strong>IndexedDB Tables</strong>.</li><li>On this page <strong>New</strong> a relation with name, both sides’ tables/fields, and type.</li><li>In Code, <code>get</code> / <code>find</code> the main table record, then read the collection by <strong>name</strong>.</li><li>After relation definition changes, update code if it still uses the old name, or delete and recreate the relation.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./table.html">IndexedDB tables</a></td><td>Create tables, columns, and data</td></tr><tr><td><a href="/kb-docs/api/indexed-db/">k.DB.indexedDb</a></td><td>Dynamic objects and queries</td></tr><tr><td><a href="./">Database overview</a></td><td>Database group menu</td></tr></tbody></table>`,11))])}const T=o(l,[["render",d]]);export{u as __pageData,T as default};
